import 'package:flutter/material.dart';import '../controllers/staff_controller.dart';class StaffPage extends StatefulWidget{final StaffController controller;const StaffPage({super.key,required this.controller});@override State<StaffPage> createState()=>_StaffPageState();}class _StaffPageState extends State<StaffPage>{@override void initState(){super.initState();widget.controller.addListener(_on);widget.controller.load();}void _on()=>setState((){});@override void dispose(){widget.controller.removeListener(_on);super.dispose();}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Serveuses'),actions:[IconButton(onPressed:widget.controller.load,icon:const Icon(Icons.refresh))]),body:widget.controller.loading?const Center(child:CircularProgressIndicator()):widget.controller.error!=null?Center(child:Text(widget.controller.error!)):ListView.builder(itemCount:widget.controller.items.length,itemBuilder:(c,i){final s=widget.controller.items[i];return ListTile(leading:CircleAvatar(child:Text(s.name.isEmpty?'?':s.name[0].toUpperCase())),title:Text(s.name),subtitle:Text(s.phone??'Téléphone non renseigné'),trailing:Icon(s.active?Icons.check_circle:Icons.block));}));}
